const $=s=>document.querySelector(s);
let token='',results=[],leadRows=[],currentView='search',leadFilters={},searchMeta=null;
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return ['http:','https:'].includes(u.protocol)?escape(u.href):'';}catch{return '';}};
function notify(message,error=false){$('#notice').hidden=false;$('#notice').className=error?'error':'';$('#notice').textContent=message;}
async function api(path,options={}){let response;try{response=await fetch('/api/'+path,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(token?{Authorization:'Bearer '+token}:{}),...options.headers}});}catch{throw Error('Servidor indisponível. Execute npm start e abra http://127.0.0.1:3000.');}const type=response.headers.get('Content-Type') || '';if(!type.includes('application/json')) throw Error('O backend não está disponível nesta hospedagem estática. Execute npm start localmente.');const data=await response.json();if(!response.ok)throw Error(data.error || 'Não foi possível concluir a operação.');return data;}
const empty=(title,description)=>`<div class="empty"><span class="empty-icon" aria-hidden="true">⌕</span><h3>${escape(title)}</h3><p>${escape(description)}</p></div>`;
const statuses={present:'Com website',absent:'Ausência confirmada',unidentified:'Website não informado',unknown:'Indisponível'};
const sourceName=source=>({osm:'OpenStreetMap',google:'Google (legado)',authorized:'Base autorizada'}[source] || 'Fonte indisponível');
const osmCredit='<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">© OpenStreetMap contributors · ODbL</a>';
function table(rows,saved=false){if(!rows.length)return empty(saved?'Sua base está pronta para o primeiro lead.':'Nenhuma empresa nesta seleção.',saved?'Adicione uma empresa de fonte autorizada ou salve um estabelecimento do OpenStreetMap.':'Experimente outra cidade, segmento ou combinação de filtros. A cobertura da fonte pode ser incompleta.');return `<div class="table-wrap"><table><thead><tr><th>Empresa / referência</th><th>Contato</th><th>Website</th><th>${saved?'Etapa':'Fonte'}</th><th>Ações</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><strong>${escape(r.name || 'Referência legada')}</strong><small>${escape(r.address || [r.city,r.state].filter(Boolean).join(' · ') || r.source_id)}</small>${r.segment?`<small>${escape(r.segment)}</small>`:''}${saved?`<small>${escape(sourceName(r.source))}</small>`:''}</td><td>${escape(r.phone || 'Indisponível')}</td><td><span class="badge ${r.website_status==='present'?'present':r.website_status==='absent'||r.website_status==='unidentified'?'opportunity':''}">${escape(statuses[r.website_status] || 'Indisponível')}</span>${safeUrl(r.website)?`<small><a href="${safeUrl(r.website)}" target="_blank" rel="noopener noreferrer">Visitar website ↗</a></small>`:''}</td><td>${saved?`<select data-stage="${r.id}" aria-label="Etapa de ${escape(r.name || r.source_id)}">${['Novo','Em contato','Qualificado','Arquivado'].map(s=>`<option ${r.stage===s?'selected':''}>${s}</option>`).join('')}</select>`:`<span class="badge">${escape(sourceName(r.source))}</span>`}</td><td>${saved?`<button data-delete="${r.id}">Remover</button>`:r.id?'<span class="badge">Na sua base</span>':`<button data-save="${i}">Salvar lead</button>`}${safeUrl(r.maps_url || r.source_url)?` <a href="${safeUrl(r.maps_url || r.source_url)}" target="_blank" rel="noopener noreferrer">Fonte ↗</a>`:''}</td></tr>`).join('')}</tbody></table></div>${rows.some(r=>r.source==='osm')?`<div class="source-credit">${osmCredit} · Dados colaborativos; verifique antes de contatar.</div>`:''}`;}
async function stats(){const s=await api('stats');for(const k of ['leads','opportunities','contacts','searches'])$('#stat-'+k).textContent=s[k];$('#nav-count').textContent=s.leads;}
const names={search:['Explorar empresas','Sua próxima oportunidade<br>começa com uma busca.','Encontre empresas, identifique oportunidades e organize sua prospecção.'],leads:['Meus leads','Boas oportunidades.<br>Próximos passos claros.','Uma base organizada para acompanhar sua prospecção.'],history:['Histórico de pesquisas','Cada pesquisa, um novo caminho.','Consulte suas buscas anteriores e retome o trabalho.'],settings:['Configurações','Sua plataforma. Suas conexões.','Configure integrações e controle o acesso aos seus dados.']};
async function view(name){currentView=name;document.querySelectorAll('.view').forEach(el=>el.hidden=el.id!=='view-'+name);document.querySelectorAll('[data-view]').forEach(el=>{el.classList.toggle('active',el.dataset.view===name);el.setAttribute('aria-current',el.dataset.view===name?'page':'false');});$('#breadcrumb').textContent=names[name][0];$('#page-title').innerHTML=names[name][1];$('#page-description').textContent=names[name][2];try{if(name==='leads')await loadLeads();if(name==='history')await history();if(name==='settings')await status();}catch(e){notify(e.message,true);}}
async function loadLeads(){leadRows=await api('leads?'+new URLSearchParams(leadFilters));$('#lead-results').innerHTML=table(leadRows,true);}
async function history(){const rows=await api('history');$('#history-results').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>Consulta</th><th>Fonte</th><th>Resultados</th><th>Quando</th><th>Status</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${escape(r.query)}</td><td>${escape(sourceName(r.source))}</td><td>${r.count}</td><td>${escape(new Date(r.created_at.replace(' ','T')+'Z').toLocaleString('pt-BR'))}</td><td>${r.status==='success'?'Concluída':'Erro'}</td></tr>`).join('')}</tbody></table></div>`:empty('Nenhuma pesquisa registrada.','As consultas aparecerão aqui quando você começar.');}
async function status(){const s=await api('status');$('#osm-status').textContent=`Sem chave de API · até ${s.result_limit} estabelecimentos por consulta. A disponibilidade é verificada ao pesquisar.`;$('#source-note').textContent=$('#source').value==='authorized'?'Pesquise os registros autorizados já cadastrados. Nenhum dado fictício é carregado.':`OpenStreetMap / Overpass · até ${s.result_limit} resultados · informe cidade/UF e nome ou segmento. Janela de até 20 km de largura; cobertura parcial. Consultas em cache por 15 minutos.`;}
function renderResults(filters){const visible=results.filter(r=>(!filters.website_status || r.website_status===filters.website_status)&&(!filters.contact || (filters.contact==='yes'?!!r.phone:!r.phone)));$('#search-results').innerHTML=table(visible); // indices must refer to visible rows
  $('#search-results').querySelectorAll('[data-save]').forEach(b=>{b.dataset.save=results.indexOf(visible[Number(b.dataset.save)]);});
  $('#results-count').textContent=visible.length;$('#results-description').textContent=`${visible.length} de ${results.length} empresas na consulta atual.${searchMeta?.cached?' Resultado em cache.':''}${searchMeta?.limited?' Limite de resultados atingido; refine a busca.':''}${searchMeta?.region?.clipped?' Região limitada a uma janela de até 20 km de largura.':''}`;
  if(searchMeta?.region){const region=document.createElement('p');region.className='source-credit';region.textContent='Região consultada: '+searchMeta.region.name;$('#search-results').append(region);}}
$('#search-form').addEventListener('submit',async e=>{e.preventDefault();const filters=Object.fromEntries(new FormData(e.target));$('#search-button').disabled=true;$('#source').disabled=true;$('#progress').hidden=false;$('#notice').hidden=true;results=[];searchMeta=null;$('#search-results').innerHTML=empty('Consultando a fonte…','Localizando a região e consultando os estabelecimentos. O serviço gratuito pode levar alguns segundos.');try{const data=await api('search',{method:'POST',body:JSON.stringify(filters)});results=data.results;searchMeta=data;renderResults(filters);await stats();}catch(e){notify(e.message,true);$('#search-results').innerHTML=empty('A pesquisa não foi concluída.',e.message);$('#results-count').textContent='0';$('#results-description').textContent='Revise os filtros ou tente novamente mais tarde.';await stats().catch(()=>{});}finally{$('#search-button').disabled=false;$('#source').disabled=false;$('#progress').hidden=true;}});
for(const name of ['website_status','contact'])$('#search-form').elements[name].addEventListener('change',()=>renderResults(Object.fromEntries(new FormData($('#search-form')))));
$('#source').addEventListener('change',()=>{results=[];searchMeta=null;$('#search-results').innerHTML=empty('Escolha seus filtros e comece a explorar.','Os resultados aparecem aqui após uma consulta.');$('#results-count').textContent='0';status().catch(e=>notify(e.message,true));});
$('#lead-filters').addEventListener('submit',e=>{e.preventDefault();leadFilters=Object.fromEntries(new FormData(e.target));loadLeads().catch(e=>notify(e.message,true));});
$('#lead-form').addEventListener('submit',async e=>{e.preventDefault();const form=e.target, button=form.querySelector('[type=submit]');button.disabled=true;$('#form-error').textContent='';try{const input=Object.fromEntries(new FormData(form));input.source='authorized';input.authorized=form.elements.authorized.checked;input.export_allowed=form.elements.export_allowed.checked;await api('leads',{method:'POST',body:JSON.stringify(input)});$('#lead-dialog').close();form.reset();notify('Lead salvo. Registros com o mesmo identificador são atualizados sem duplicação.');await stats();if(currentView==='leads')await loadLeads();}catch(e){$('#form-error').textContent=e.message;}finally{button.disabled=false;}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.view)await view(b.dataset.view);if(b.hasAttribute('data-close'))b.closest('dialog').close();if(b.id==='add-lead')$('#lead-dialog').showModal();if(b.id==='policy-open')$('#policy-dialog').showModal();if(b.id==='refresh-history')await history();if(b.dataset.save){b.disabled=true;const r=results[Number(b.dataset.save)];const saved=await api('leads',{method:'POST',body:JSON.stringify({source:r.source,source_id:r.source_id})});r.id=saved.id;notify('Lead OpenStreetMap salvo com origem e licença ODbL.');b.textContent='Salvo';await stats();}if(b.dataset.delete){if(!confirm('Remover este lead da sua base?'))return;await api('leads/'+b.dataset.delete,{method:'DELETE'});await loadLeads();await stats();notify('Lead removido.');}if(b.dataset.export){const response=await fetch('/api/export?'+new URLSearchParams({...leadFilters,format:b.dataset.export}),{headers:token?{Authorization:'Bearer '+token}:{}});if(!response.ok){const err=await response.json();throw Error(err.error);}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='leads.'+b.dataset.export;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Exportação concluída com registros elegíveis, origem e atribuição quando aplicável.');}}catch(err){notify(err.message,true);if(b.dataset.save)b.disabled=false;}});
document.addEventListener('change',async e=>{if(e.target.dataset.stage)try{await api('leads/'+e.target.dataset.stage,{method:'PATCH',body:JSON.stringify({stage:e.target.value})});notify('Etapa atualizada.');}catch(err){notify(err.message,true);await loadLeads();}});
$('#token-form').addEventListener('submit',async e=>{e.preventDefault();token=$('#token').value;$('#token').value='';try{await stats();await status();notify('Acesso validado nesta sessão.');}catch(err){notify(err.message,true);}});
$('#search-results').innerHTML=empty('Um mercado inteiro para explorar.','Pesquise em uma fonte oficial ou adicione dados autorizados à sua base. Seus resultados aparecerão aqui.');
Promise.all([stats(),status()]).catch(e=>notify(e.message,true));
